TR = {}
def track(k, ic, t, d): TR[k] = dict(ic=ic, t=t, d=d, lessons=[])
def les(k, id, t, idea, rules, ex, q, r=()): TR[k]['lessons'].append(dict(id=id, t=t, idea=idea, rules=rules, ex=ex, q=q, r=list(r), s=[]))

